content.content:
:root {
  --fundo: #f4f2f8;
  --cartao: #ffffff;
  --texto: #1c1830;
  --muted: #6b6680;
  --borda: #e4e0ee;
  --primaria: #5b21b6;
  --primaria-2: #db2777;
  --primaria-suave: #ede9fe;
  --perigo: #dc2626;
  --sucesso: #15803d;
  --ouro: #f59e0b;
  --raio: 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fundo: #0f0d17;
    --cartao: #1a1726;
    --texto: #f1eff8;
    --muted: #a19bb8;
    --borda: #2d2840;
    --primaria: #a78bfa;
    --primaria-2: #f472b6;
    --primaria-suave: #2a2142;
    --perigo: #f87171;
    --sucesso: #4ade80;
    color-scheme: dark;
  }
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--fundo); color: var(--texto); line-height: 1.45; }
a { color: var(--primaria); text-decoration: none; }
a:hover { text-decoration: underline; }
h1, h2, h3 { margin: 0 0 .6rem; line-height: 1.2; }
h1 { font-size: 1.35rem; }
h2 { font-size: 1.1rem; }
40:h2 { font-size: 1.1rem; }

